/** Server-owned, immutable screens: every mutation rechecks ownership and persistent state. */
public final class FishingScreens {
 public static boolean isFishing(ScreenHandler h){return h instanceof Menu;}
 public static void open(FishingMod m,ServerPlayerEntity p,String page){open(m,p,page,0);}
 static String configPage(String page){return switch(page){case "perfil"->"profile";case "armazem"->"storage";case "areas"->"areas";case "varas"->"rods";case "iscas"->"baits";case "bolas"->"pokeballs";case "melhorias"->"upgrades";case "tempo"->"time-shop";case "missoes"->"missions";case "conquistas"->"achievements";case "ranking"->"rankings";case "recordes"->"records";case "torneios"->"tournaments";case "museu"->"museum";case "tesouros"->"treasures";case "prestigio"->"prestige";default->page.contains(":")?"storage":page;};}
 static JsonObject settings(FishingMod m,String page){return m.rules.files.getOrDefault("menus/"+configPage(page),new JsonObject());}
 public static void open(FishingMod m,ServerPlayerEntity p,String page,int index){
  page=switch(page){case "venda"->"armazem";case "pokebolas"->"bolas";case "recompensas"->"conquistas";default->page;};
  if(m.store==null)return;
  final String targetPage=page;
  if(page.equals("main")&&!m.sessions.protectedPlayer(p)&&m.menuIntegrationReady&&MenuBridge.openConfigured(m,p))return;
  p.openHandledScreen(new SimpleNamedScreenHandlerFactory((sync,inv,user)->new Menu(sync,p,m,targetPage,index),Text.literal(str(settings(m,page),"title","✦ ZORYKAI · "+page).replace("&","§"))));
 }
 interface Work{void run()throws Exception;}
 static final class Menu extends GenericContainerScreenHandler {
  final ServerPlayerEntity owner;final FishingMod m;final String page;final int index;final Map<Integer,Work> actions=new HashMap<>();long clicked;
  Menu(int sync,ServerPlayerEntity p,FishingMod mod,String page,int index){super(ScreenHandlerType.GENERIC_9X6,sync,p.getInventory(),new SimpleInventory(54),6);owner=p;m=mod;this.page=page;this.index=index;
   try{render();}catch(Exception e){m.fail(e);button(22,Items.BARRIER,"§cIndisponível",List.of("§7"+e.getMessage()),null);}
   button(49,Items.ARROW,"§b"+(page.equals("main")?"Fechar":"Voltar"),List.of(),()->{if(page.equals("main"))p.closeHandledScreen();else open(m,p,"main");});
  }
  void render()throws Exception{var p=owner;var d=m.data.profile(p.getUuid());
   if(page.equals("main")){
    button(0,Items.FISHING_ROD,m.sessions.protectedPlayer(p)?"§bSair da pesca":"§bEntrar na pesca",List.of("§7Inventário original reservado e restaurado na saída."),()->{if(m.sessions.protectedPlayer(p))m.sessions.exit(p);else m.sessions.enter(p);open(m,p,"main");});
    String[] pages={"areas","armazem","perfil","varas","iscas","bolas","melhorias","missoes","tempo","conquistas","torneios","ranking","dex","museu","prestigio","tesouros","pendencia","recordes","premios","eventos"};for(int i=0;i<pages.length;i++){String target=pages[i];button(i+2,Items.BOOK,"§b"+target,List.of("§7Clique para abrir."),()->open(m,p,target));}
   }else if(page.equals("perfil")){button(13,Items.NAME_TAG,"§b"+p.getGameProfile().getName(),List.of("§7Nível: "+m.rules.level(d.xp)+" · XP: "+d.xp,"§7Capturas: "+d.captures+" · Vendas: "+d.sales,"§7Shiny: "+d.shinyCaptures+" · Espécies: "+d.dex.size(),"§7Tempo: "+m.sessions.balance(m.sessions.renew(p))/60+" minutos","§7Prestígio: "+d.prestige+" · Capacidade: "+d.capacity),null);
   }else if(page.startsWith("peixe:")){String id=page.substring(6);var f=m.engine.fish(p.getUuid()).stream().filter(x->x.id().equals(id)&&x.state().equals("AVAILABLE")).findFirst().orElseThrow();button(13,Items.COD,"§b"+f.species(),fishLore(f),null);button(20,Items.GOLD_INGOT,"§bVender por $"+f.value(),List.of("§7Clique e confirme."),()->confirm(m,p,"Vender captura",()->m.finance.sell(p,List.of(id))));button(22,Items.NETHER_STAR,f.favourite()?"§bDesproteger":"§bFavoritar / proteger",List.of(),()->{m.engine.favourite(p.getUuid(),id);open(m,p,page);});button(24,Items.BARRIER,"§cSoltar definitivamente",List.of("§7Capturas favoritas são protegidas."),()->confirm(m,p,"Soltar captura",()->m.engine.release(p.getUuid(),id)));
   }else if(page.equals("armazem")||page.startsWith("armazem:")){
    String query=page.contains(":")?page.substring(8):"all";String filter=query.split("@",2)[0],order=query.contains("@")?query.split("@",2)[1]:"recent";Comparator<GameEngine.Fish> sorting=switch(order){case "valor"->Comparator.comparing(GameEngine.Fish::value).reversed();case "tamanho"->Comparator.comparingDouble(GameEngine.Fish::metres).reversed();case "especie"->Comparator.comparing(GameEngine.Fish::species);default->Comparator.comparingLong(GameEngine.Fish::captured).reversed();};var list=m.engine.fish(p.getUuid()).stream().filter(x->x.state().equals("AVAILABLE")).filter(x->filter.equals("all")||filter.equals("shiny")&&x.shiny()||filter.equals("favoritos")&&x.favourite()||x.species().contains(filter)).sorted(sorting).toList();int start=pageStart(list.size());for(int i=start;i<Math.min(list.size(),start+36);i++){var f=list.get(i);button(i-start,Items.COD,"§b"+f.species()+(f.shiny()?" ★":"")+(f.favourite()?" ♥":""),fishLore(f),()->open(m,p,"peixe:"+f.id()));}arrows(list.size());button(45,Items.GOLD_INGOT,"§bVender lote desta página",List.of("§7Favoritos nunca são vendidos."),()->{var ids=list.subList(start,Math.min(list.size(),start+36)).stream().filter(x->!x.favourite()).map(GameEngine.Fish::id).toList();confirm(m,p,"Vender "+ids.size()+" capturas",()->m.finance.sell(p,ids));});button(46,Items.NETHER_STAR,"§bFavoritos",List.of(),()->open(m,p,"armazem:favoritos"));button(47,Items.EMERALD,"§bSomente shiny",List.of(),()->open(m,p,"armazem:shiny"));button(48,Items.CHEST,"§bExpandir armazém",List.of("§7Preço: $"+decimal(m.rules.get("storage"),"expansionPrice",10000)),()->confirm(m,p,"Expandir armazém",()->m.finance.buy(p,"capacity","capacity")));
    button(50,Items.CLOCK,"§bOrdenar por valor",List.of(),()->open(m,p,"armazem:"+filter+"@valor"));button(52,Items.COMPASS,"§bOrdenar por tamanho",List.of(),()->open(m,p,"armazem:"+filter+"@tamanho"));
   }else if(page.equals("areas")){int slot=0;for(var lake:m.config.lakes.values()){if(slot>=36)break;button(slot++,Items.MAP,"§b"+lake.name(),List.of("§7Nível mínimo: "+lake.minimumLevel(),"§7Pesca: "+(m.engine.allowed(p,lake,d)?"liberada":"bloqueada"),"§7Exploração livre; requisitos só para pescar."),null);}
   }else if(Set.of("varas","iscas","bolas","melhorias","tempo").contains(page)){
    String file=switch(page){case "varas"->"rods";case "iscas"->"baits";case "bolas"->"pokeballs";case "melhorias"->"upgrades";default->"time-shop";};String type=switch(page){case "varas"->"rod";case "iscas"->"bait";case "bolas"->"ball";case "melhorias"->"upgrade";default->"time";};int slot=0;
    for(var def:rows(m.rules.get(file))){String id=str(def,"id","");boolean own=type.equals("rod")&&d.rods.containsKey(id)||type.equals("bait")&&(bool(def,"infinite",false)||d.baits.getOrDefault(id,0)>0)||type.equals("ball")&&(bool(def,"infinite",false)||d.balls.getOrDefault(id,0)>0);int count=type.equals("bait")?d.baits.getOrDefault(id,0):type.equals("ball")?d.balls.getOrDefault(id,0):0;button(slot++,Items.PAPER,"§b"+str(def,"name",id),List.of("§7Preço: $"+decimal(def,"price",0),"§7Estoque: "+(bool(def,"infinite",false)?"ilimitado":count),"§7"+(own?"Clique para selecionar. Compra na linha abaixo.":"Clique para comprar.")),()->{if(own){m.data.update(p.getUuid(),v->{switch(type){case "rod"->v.selectedRod=id;case "bait"->v.selectedBait=id;case "ball"->v.selectedBall=id;}return null;});if(m.sessions.active(p))m.engine.equip(p);open(m,p,page);}else confirm(m,p,"Comprar "+id,()->m.finance.buy(p,type,id));});if(slot+17<36&&!bool(def,"infinite",false)&&!type.equals("rod"))button(slot+17,Items.GOLD_NUGGET,"§bComprar "+id,List.of("§7$"+decimal(def,"price",0)),()->confirm(m,p,"Comprar "+id,()->m.finance.buy(p,type,id)));}
   }else if(page.equals("missoes")){int slot=0;for(var q:m.progress.quests()){if(slot>=36)break;String id=str(q,"id","");var state=m.progress.quest(d,q);button(slot++,Items.WRITABLE_BOOK,"§b"+str(q,"name",id),List.of("§7"+str(q,"period","STORY"),"§7Progresso: "+state.progress+"/"+num(q,"target",1),"§7Clique para resgatar se concluída."),()->{m.progress.claimQuest(p,id);open(m,p,page);});}
   }else if(page.equals("conquistas")){int slot=0;for(var q:rows(m.rules.get("achievements"))){String id=str(q,"id","");button(slot++,Items.GOLDEN_APPLE,"§b"+str(q,"name",id),List.of("§7Progresso: "+m.progress.statistic(d,str(q,"stat","captures"))+"/"+num(q,"target",1),"§7Recebida: "+d.achievements.contains(id)),()->{m.progress.claimAchievement(p,id);open(m,p,page);});}
   }else if(page.equals("torneios")){int slot=0;for(var q:rows(m.rules.get("tournaments/example"))){String id=str(q,"id","");var state=m.data.global("tournament:"+id);button(slot++,Items.CLOCK,"§b"+str(q,"name",id),List.of("§7Estado: "+str(state,"state","AGUARDANDO"),"§7Modalidade: "+str(q,"metric","LARGEST"),"§7Clique para entrar ou resgatar prêmio."),()->{if(str(state,"state","").equals("ACTIVE"))m.progress.joinTournament(p,id);else m.progress.claimTournament(p,id,str(state,"run",""));open(m,p,page);});}
   }else if(page.equals("dex")||page.startsWith("dex:")){String search=page.contains(":")?page.substring(4):"";var list=d.dex.entrySet().stream().filter(x->search.isBlank()||search.equals("shiny")&&x.getValue().shiny>0||x.getKey().contains(search)).sorted(Map.Entry.comparingByKey()).toList();int start=pageStart(list.size());for(int i=start;i<Math.min(list.size(),start+36);i++){var e=list.get(i);button(i-start,Items.BOOK,"§b"+e.getKey(),List.of("§7Encontrados: "+e.getValue().seen,"§7Capturados: "+e.getValue().caught,"§7Shiny: "+e.getValue().shiny,"§7Maior: "+e.getValue().largest+" m","§7Menor: "+(e.getValue().caught>0?e.getValue().smallest:"—")+" m"),null);}arrows(list.size());
   }else if(page.equals("museu")){var favourites=m.engine.fish(p.getUuid()).stream().filter(x->x.favourite()&&x.state().equals("AVAILABLE")).toList();int slot=0;for(var f:favourites.stream().limit(24).toList())button(slot++,Items.COD,"§b♥ "+f.species(),fishLore(f),()->open(m,p,"peixe:"+f.id()));for(String achievement:d.achievements.stream().limit(12).toList())button(slot++,Items.GOLD_INGOT,"§bTroféu: "+achievement,List.of("§7Conquista permanente."),null);
   }else if(page.equals("ranking")||page.startsWith("ranking:")){String stat=page.contains(":")?page.substring(8):"captures";var list=m.data.profiles().stream().sorted(Comparator.<Map.Entry<UUID,com.zorykai.fishing.core.PlayerData>>comparingDouble(x->m.progress.statistic(x.getValue(),stat)).reversed().thenComparing(x->x.getKey().toString())).toList();for(int i=0;i<Math.min(num(m.rules.get("rankings"),"displayLimit",20),Math.min(36,list.size()));i++){var row=list.get(i);button(i,Items.GOLD_INGOT,"§b#"+(i+1)+" "+(row.getValue().name==null||row.getValue().name.isBlank()?row.getKey():row.getValue().name),List.of("§7"+stat+": "+m.progress.statistic(row.getValue(),stat)),null);}int slot=45;for(String metric:List.of("captures","largest","level","species","tournaments")){String target=metric;button(slot==49?++slot:slot++,Items.PAPER,"§b"+metric,List.of(),()->open(m,p,"ranking:"+target));}
   }else if(page.equals("recordes")){var records=m.data.global("records").entrySet().stream().sorted(Comparator.<Map.Entry<String,JsonElement>>comparingDouble(x->decimal(x.getValue().getAsJsonObject(),"metres",0)).reversed()).toList();int start=pageStart(records.size());for(int i=start;i<Math.min(records.size(),start+36);i++){var row=records.get(i);button(i-start,Items.GOLD_INGOT,"§b"+row.getKey(),List.of("§7Pescador: "+str(row.getValue().getAsJsonObject(),"name",""),"§7Tamanho: "+decimal(row.getValue().getAsJsonObject(),"metres",0)+" m"),null);}arrows(records.size());
   }else if(page.equals("premios")){var runs=new ArrayList<JsonObject>();for(var def:rows(m.rules.get("tournaments/example"))){var state=m.data.global("tournament:"+str(def,"id",""));if(str(state,"state","").equals("FINISHED"))runs.add(state);}for(var entry:m.data.global("tournament-history").entrySet())runs.add(entry.getValue().getAsJsonObject());var relevant=runs.stream().filter(x->x.has("ranking")&&x.getAsJsonArray("ranking").asList().stream().anyMatch(y->str(y.getAsJsonObject(),"player","").equals(p.getUuidAsString()))).toList();int start=pageStart(relevant.size());for(int i=start;i<Math.min(relevant.size(),start+36);i++){var run=relevant.get(i);String id=str(run,"definition",""),runId=str(run,"run","");button(i-start,Items.GOLD_INGOT,"§b"+id,List.of("§7Edição: "+runId,"§7Recebido: "+d.counters.containsKey("reward:tournament:"+runId)),()->{m.progress.claimTournament(p,id,runId);open(m,p,page);});}arrows(relevant.size());
   }else if(page.equals("eventos")){var events=m.data.global("events");int slot=0;for(var def:rows(m.rules.get("events/example"))){String id=str(def,"id","");long ends=events.has(id)?events.getAsJsonObject(id).get("ends").getAsLong():0;button(slot++,Items.CLOCK,"§b"+str(def,"name",id),List.of("§7Estado: "+(ends>System.currentTimeMillis()?"ativo":"inativo"),"§7Restam: "+Math.max(0,(ends-System.currentTimeMillis())/1000)+" segundos","§7Lagos: "+(def.has("lakes")?def.get("lakes"):"todos")),null);}
   }else if(page.equals("prestigio")){button(22,Items.NETHER_STAR,"§bPrestígio "+d.prestige,List.of("§7Requer nível máximo.","§7Mantém varas, capturas e progresso permanente.","§7Clique para confirmar."),()->confirm(m,p,"Avançar prestígio",()->m.progress.prestige(p)));
   }else if(page.equals("tesouros")){int slot=0;for(var e:d.counters.entrySet())if(e.getKey().equals("fragments")||e.getKey().startsWith("treasure:"))button(slot++,Items.DIAMOND,"§b"+e.getKey(),List.of("§7Quantidade: "+e.getValue(),"§7Clique para retirar após sair da pesca."),()->{m.delivery.claim(p,e.getKey());open(m,p,page);});
    for(String reserve:m.delivery.reserves(p.getUuid()))button(slot++,Items.CHEST,"§bItens preservados",List.of("§7"+reserve,"§7Retire fora da pesca."),()->{m.delivery.claim(p,reserve);open(m,p,page);});
   }else if(page.equals("pendencia")){var tx=m.finance.pending(p.getUuid());button(22,Items.PAPER,"§bTransação",tx==null?List.of("§7Nenhuma pendência."):List.of("§7"+tx.id(),"§7"+tx.stage(),"§7$"+tx.amount(),"§7Clique para tentar concluir aplicação confirmada."),()->{m.finance.recover(p.getUuid());open(m,p,page);});
   }else throw new IllegalArgumentException("Menu inexistente");
  }
  int pageStart(int size){return Math.min(Math.max(0,index),Math.max(0,(size-1)/36))*36;}
  void arrows(int size){if(index>0)button(51,Items.ARROW,"§bAnterior",List.of(),()->open(m,owner,page,index-1));if((index+1)*36<size)button(53,Items.ARROW,"§bPróxima",List.of(),()->open(m,owner,page,index+1));}
  List<String> fishLore(GameEngine.Fish f){return List.of("§7Lago: "+f.lake(),"§7Tamanho: "+String.format(Locale.ROOT,"%.2f m",f.metres())+" · "+f.size(),"§7Raridade: "+f.rarity()+" · Shiny: "+f.shiny(),"§7Valor: $"+f.value(),"§7Favorito: "+f.favourite(),"§7Data: "+java.time.Instant.ofEpochMilli(f.captured()).atZone(java.time.ZoneId.of("America/Sao_Paulo")).toLocalDate(),"§8ID: "+f.id());}
  void button(int slot,Item item,String name,List<String> lore,Work action){var cfg=settings(m,page);if(cfg.has("buttons")&&cfg.getAsJsonObject("buttons").has(Integer.toString(slot))){var override=cfg.getAsJsonObject("buttons").getAsJsonObject(Integer.toString(slot));if(!bool(override,"enabled",true))return;slot=num(override,"slot",slot);name=str(override,"name",name).replace("&","§");if(override.has("item"))item=net.minecraft.registry.Registries.ITEM.get(net.minecraft.util.Identifier.of(str(override,"item","minecraft:paper")));if(override.has("lore"))lore=override.getAsJsonArray("lore").asList().stream().map(x->x.getAsString().replace("&","§")).toList();}if(slot<0||slot>=54)return;var stack=new ItemStack(item);stack.set(DataComponentTypes.CUSTOM_NAME,Text.literal(name));stack.set(DataComponentTypes.LORE,new LoreComponent(lore.stream().map(x->(Text)Text.literal(x)).toList()));getInventory().setStack(slot,stack);if(action!=null)actions.put(slot,action);}
  @Override public boolean canUse(PlayerEntity p){return p==owner;}
  @Override public ItemStack quickMove(PlayerEntity p,int slot){return ItemStack.EMPTY;}
  @Override public boolean canInsertIntoSlot(ItemStack stack,net.minecraft.screen.slot.Slot slot){return false;}
  @Override public void onSlotClick(int slot,int button,SlotActionType type,PlayerEntity p){if(p!=owner||p.currentScreenHandler!=this||type!=SlotActionType.PICKUP||button!=0||System.currentTimeMillis()-clicked<250)return;clicked=System.currentTimeMillis();var action=actions.get(slot);if(action!=null)try{action.run();}catch(Exception e){FishingMod.tell(owner,e.getMessage());m.log(e);}}
 }
 static void confirm(FishingMod m,ServerPlayerEntity p,String label,Work work){p.openHandledScreen(new SimpleNamedScreenHandlerFactory((sync,inv,user)->{var menu=new Menu(sync,p,m,"main",0);menu.getInventory().clear();menu.actions.clear();menu.button(20,Items.LIME_WOOL,"§aConfirmar: "+label,List.of(),()->{p.closeHandledScreen();work.run();});menu.button(24,Items.RED_WOOL,"§cCancelar",List.of(),()->open(m,p,"main"));return menu;},Text.literal(label)));}
}
